function canBeEqual(target, arr) {
  // Breadth-first search over every arrangement reachable from arr by reversals.
  const goal = target.join(',');
  const seen = new Set([arr.join(',')]);
  const queue = [arr.slice()];
  for (let head = 0; head < queue.length; head++) {
    const current = queue[head];
    if (current.join(',') === goal) return true;
    for (let i = 0; i < current.length; i++)
      for (let j = i + 1; j < current.length; j++) {
        const next = current.slice(0, i).concat(current.slice(i, j + 1).reverse(), current.slice(j + 1));
        const key = next.join(',');
        if (!seen.has(key)) { seen.add(key); queue.push(next); }
      }
  }
  return false;
}

