function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 6);
  const top = [2, 5, 1000][Math.floor(rand() * 3)];
  const target = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const arr = target.slice();
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  const mode = rand();
  if (mode < 0.35) {
    const i = Math.floor(rand() * n);
    arr[i] = 1 + Math.floor(rand() * top);
  } else if (mode < 0.45) {
    return [target, Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
  }
  return [target, arr];
}
